struct Info { unsigned long RefCount; int id; };
struct Counted {
    void* Data; Info* Info_;
    void Release() { if (Info_) { if (--Info_->RefCount == 0) g_log[g_n++] = Info_->id; } Data = 0; Info_ = 0; }
